<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/functions.php';require_login();$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT t.*,p.nama,p.alamat,p.nomor_telepon,l.nama_layanan,k.username FROM transaksi t JOIN pelanggan p ON t.id_pelanggan=p.id_pelanggan JOIN layanan l ON t.id_layanan=l.id_layanan JOIN kasir k ON t.id_kasir=k.id_kasir WHERE t.id_transaksi=?');$s->bind_param('i',$id);$s->execute();$r=$s->get_result()->fetch_assoc();if(!$r)die('Nota tidak ditemukan.');?>
